    },
    {
      "hunk_id": "H024",
      "decision": "SOL",
      "reason": "The reordered allies and enemies do not change the tangled battle."
    },
    {
      "hunk_id": "H025",
      "decision": "SOL",
      "reason": "“Staggering mess” conveys the severe aftermath without changing the event."
    },
    {
      "hunk_id": "H026",
      "decision": "SOL",
      "reason": "“Uninvited” and “filthy and wrecked” retain the unwanted guests’ mess and the homeowner joke."
    },
    {
      "hunk_id": "H027",
      "decision": "SOL",
      "reason": "SOL preserves the workload and the need to handle the aftermath before recovering."
    },
    {
      "hunk_id": "H028",
      "decision": "SOL",
