    },
    {
      "hunk_id": "H029",
      "decision": "SOL",
      "reason": "The shorter instruction keeps the three choices and requires him to hear them before choosing."
    },
    {
      "hunk_id": "H030",
      "decision": "SOL",
      "reason": "“Step in” preserves that the Medicine King Hall Master was first to act."
    },
    {
      "hunk_id": "H031",
      "decision": "BASE",
      "reason": "SOL drops the explicit cue that he then spoke, weakening the transition into the quoted threat."
    },
    {
      "hunk_id": "H032",
      "decision": "BASE",
      "reason": "The Korean says he keeps ignoring the speaker’s instructions; SOL changes that to ignoring the speaker personally."
    },
    {
      "hunk_id": "H033",
      "decision": "SOL",
      "reason": "SOL keeps both his beginning to rest and the others’ fierce debate."
    },
    {
      "hunk_id": "H034",
      "decision": "SOL",
      "reason": "SOL keeps both possible causes of his corpse-like pallor."
    },
    {
      "hunk_id": "H035",
      "decision": "BASE",
      "reason": "The Korean says Hyuk Mujin stated it bluntly; SOL instead says he was certain."
    },
    {
      "hunk_id": "H036",
      "decision": "SOL",
      "reason": "“The needle. No question” keeps the emphatic joke, and “have a position” fits the Korean idiom."
    },
    {
      "hunk_id": "H037",
      "decision": "SOL",
      "reason": "SOL retains Jin Wikyung’s relenting and the role others played in it."
    },
    {
      "hunk_id": "H038",
      "decision": "SOL",
      "reason": "“Who calls himself” keeps the contemptuous quack remark without changing its target."
    },
    {
      "hunk_id": "H039",
      "decision": "SOL",
      "reason": "SOL preserves the victory and uncertainty about whether every threat is gone."
    },
    {
      "hunk_id": "H040",
      "decision": "SOL",
      "reason": "“Wash away” is a natural recast of dispelling even the slightest worry."
    },
    {
      "hunk_id": "H041",
      "decision": "SOL",
      "reason": "SOL keeps the Bow Saint’s return after decades and her reappearance before people."
    },
    {
      "hunk_id": "H042",
      "decision": "SOL",
      "reason": "“As soon as the battle ended” and “those few words” preserve the timing and brevity."
    },
    {
      "hunk_id": "H043",
      "decision": "SOL",
      "reason": "SOL preserves Peng Cheolyeong’s titles and his return with the family members able to travel."
    },
    {
      "hunk_id": "H044",
      "decision": "SOL",
      "reason": "“Hadn’t betrayed us alone” preserves that others in the Murong Family were involved."
    },
    {
      "hunk_id": "H045",
      "decision": "SOL",
      "reason": "SOL keeps the inference and the messenger eagle’s confirmation of part of it."
    },
    {
      "hunk_id": "H046",
      "decision": "SOL",
      "reason": "“There was trouble” preserves the report of events in Hebei."
    },
    {
      "hunk_id": "H047",
      "decision": "SOL",
      "reason": "SOL retains both the forced rest and how difficult it was to take the paperwork from him."
    },
    {
      "hunk_id": "H048",
      "decision": "BASE",
      "reason": "SOL omits Jin Wikyung and Hebei, removing explicit names that anchor who received the news and where the trouble occurred."
    },
    {
      "hunk_id": "H049",
      "decision": "SOL",
      "reason": "SOL preserves the two targets, the pretext, and the ambush."
    },
    {
      "hunk_id": "H050",
      "decision": "SOL",
      "reason": "The shorter phrasing keeps the bloodshed’s scope and location."
    },
    {
      "hunk_id": "H051",
      "decision": "SOL",
      "reason": "SOL preserves the surprise, heavy losses, and desperate defense."
    },
    {
      "hunk_id": "H052",
      "decision": "BASE",
      "reason": "The Korean says an irreversible event would have occurred; SOL narrows that to damage beyond repair."
    },
    {
      "hunk_id": "H053",
      "decision": "BASE",
      "reason": "SOL omits Peng Cheolyeong’s name at his arrival, where the source identifies him explicitly."
    },
    {
      "hunk_id": "H054",
      "decision": "SOL",
      "reason": "SOL keeps the roar, the returning family members, and the Jinzhou Yan martial artists."
    },
    {
      "hunk_id": "H055",
      "decision": "BASE",
      "reason": "SOL replaces the explicit Hebei Peng Family with “they,” obscuring whose fight would have been difficult."
    },
    {
      "hunk_id": "H056",
      "decision": "SOL",
      "reason": "SOL preserves the devastation and the thousand hastily assembled, exhausted troops."
    },
    {
      "hunk_id": "H057",
      "decision": "SOL",
      "reason": "“At their head stood” keeps the giant’s position and the family head’s reluctance to step ahead."
    },
    {
      "hunk_id": "H058",
      "decision": "SOL",
      "reason": "“As good as decided” preserves that the outcome was effectively settled."
    },
    {
      "hunk_id": "H059",
      "decision": "SOL",
      "reason": "SOL conveys a defeat from which they could never recover."
    },
    {
      "hunk_id": "H060",
      "decision": "BASE",
      "reason": "“Crushed” understates the Murong Family’s destruction; the source says it was annihilated."
    },
    {
      "hunk_id": "H061",
      "decision": "BASE",
      "reason": "SOL turns the narrator’s uncertain “글쎄” into a definite prediction that they would not get far."
    },
    {
      "hunk_id": "H062",
      "decision": "SOL",
      "reason": "“We have eyes everywhere” keeps the claim of comprehensive surveillance."
    },
    {
      "hunk_id": "H063",
      "decision": "SOL",
      "reason": "“Wasn’t boasting” naturally conveys that Jin Wikyung’s confidence was justified."
    },
    {
      "hunk_id": "H064",
      "decision": "BASE",
      "reason": "SOL drops “for now,” omitting the source’s contrast between future danger and the present balance of power."
    },
    {
      "hunk_id": "H065",
      "decision": "SOL",
      "reason": "“Without breaking through” preserves the obstacle and reads naturally."
    },
    {
      "hunk_id": "H066",
      "decision": "BASE",
      "reason": "SOL changes the steppe from the outlaws’ final destination to their refuge."
    },
    {
      "hunk_id": "H067",
      "decision": "SOL",
      "reason": "SOL keeps the order to pursue them to the ends of the earth."
    },
    {
      "hunk_id": "H068",
      "decision": "SOL",
      "reason": "“Victor of the great battle” and “brought … to heel” retain the victory and hunting-dog image."
    },
    {
      "hunk_id": "H069",
      "decision": "SOL",
      "reason": "SOL preserves the warning about future trouble and addresses Temur directly."
    },
    {
      "hunk_id": "H070",
      "decision": "BASE",
      "reason": "The Korean says he dreamed of uniting the steppe under himself as Great Khan; SOL changes that to ruling the grasslands."
    },
    {
      "hunk_id": "H071",
      "decision": "SOL",
      "reason": "“Of course he did” keeps the matter-of-fact judgment."
    },
    {
      "hunk_id": "H072",
      "decision": "SOL",
      "reason": "SOL preserves both his defeat and his cowardly betrayal out of fear of death."
    },
    {
      "hunk_id": "H073",
      "decision": "SOL",
      "reason": "SOL preserves the pretext for his defeat and the distinction between it and his betrayal."
    },
    {
      "hunk_id": "H074",
      "decision": "SOL",
      "reason": "The sentence break keeps the contrast and the threat from his own tribespeople."
    },
    {
      "hunk_id": "H075",
      "decision": "BASE",
      "reason": "The Korean says Jin Wikyung grips the leash tightly; SOL drops that force."
    },
    {
      "hunk_id": "H076",
      "decision": "SOL",
      "reason": "“Every other choice” preserves that his alternatives disappeared."
    },
    {
      "hunk_id": "H077",
      "decision": "SOL",
      "reason": "“Holding his leash” keeps the image and the need to retain him as an ally."
    },
    {
      "hunk_id": "H078",
      "decision": "SOL",
      "reason": "“Just looking at you” naturally preserves that seeing Temur makes him angry."
    },
    {
      "hunk_id": "H079",
      "decision": "SOL",
      "reason": "“Once and for all” keeps the resolve to handle the remaining problem decisively."
    },
    {
      "hunk_id": "H080",
      "decision": "SOL",
      "reason": "“Drew every eye” preserves the armor’s attention-grabbing effect."
    },
    {
      "hunk_id": "H081",
      "decision": "SOL",
      "reason": "“Manner of speaking” is a natural equivalent for his stiff speech."
    },
    {
      "hunk_id": "H082",
      "decision": "SOL",
      "reason": "SOL keeps the deliberate frown directed at Jeong Hogun."
    },
    {
      "hunk_id": "H083",
      "decision": "BASE",
      "reason": "SOL translates the Korean “add your spoon” idiom literally; BASE conveys the joke’s meaning as taking credit."
    },
    {
      "hunk_id": "H084",
      "decision": "SOL",
      "reason": "SOL keeps the reminder that the narrator helped first and the Imperial Palace counterfactual."
    },
    {
      "hunk_id": "H085",
      "decision": "SOL",
      "reason": "SOL preserves the surprise at his straightforward admission."
    },
    {
      "hunk_id": "H086",
      "decision": "SOL",
      "reason": "The speakers are clear from context, and SOL keeps their shared chuckle."
    },
    {
      "hunk_id": "H087",
      "decision": "SOL",
      "reason": "SOL preserves the mutual gratitude without changing its meaning."
    },
    {
      "hunk_id": "H088",
      "decision": "SOL",
      "reason": "The self-correction keeps the speaker’s hesitation and emphasis on the favor’s difficulty."
    },
    {
      "hunk_id": "H089",
      "decision": "BASE",
      "reason": "SOL adds “you mean,” turning the statement into a clarifying question."
    },
    {
      "hunk_id": "H090",
      "decision": "SOL",
      "reason": "The reordered adverb keeps the quiet nod and immediate answer."
    },
    {
      "hunk_id": "H091",
      "decision": "SOL",
      "reason": "Jeong Hogun is clear from context, so the shorter attribution preserves the exchange."
    },
    {
      "hunk_id": "H092",
      "decision": "SOL",
      "reason": "The contrast remains clear: he cannot grant a personal favor, but can obey an order."
    },
    {
      "hunk_id": "H093",
      "decision": "SOL",
      "reason": "The speaker is clear from context, and SOL keeps the realization and short laugh."
    },
    {
      "hunk_id": "H094",
      "decision": "BASE",
      "reason": "The Korean asks why he has to go to such lengths; SOL shifts it to why the procedure must be that way."
    },
    {
      "hunk_id": "H095",
      "decision": "SOL",
      "reason": "“Military code” is a natural rendering of the Great Nation’s military law and custom."
    },
    {
      "hunk_id": "H096",
      "decision": "SOL",
      "reason": "The exclamation keeps the narrator’s amused impression of him."
    },
    {
      "hunk_id": "H097",
      "decision": "SOL",
      "reason": "SOL preserves the thought that people like Jeong Hogun make the Great Nation possible."
    },
    {
      "hunk_id": "H098",
      "decision": "SOL",
      "reason": "“Gave him what he wanted” naturally conveys that the narrator then spoke as requested."
    },
    {
      "hunk_id": "H099",
      "decision": "SOL",
      "reason": "SOL preserves the respectful bow and the sense that the exchange was set aside."
    },
    {
      "hunk_id": "H100",
      "decision": "SOL",
      "reason": "“Last threat left to deal with” preserves Liaoning’s role as the final remaining danger."
    },
    {
      "hunk_id": "H101",
      "decision": "BASE",
      "reason": "SOL omits that Jeong Hogun struck his armor in response to the narrator’s order."
    },
    {
      "hunk_id": "H102",
      "decision": "SOL",
      "reason": "“Obey the … command” keeps the formal pledge of obedience."
    }
  ]
}

